// ============================================================
// ZMP — Parser email Airbnb / Booking.com
// Basato sui formati reali (giugno 2026):
//  A) Airbnb  'Prenotazione confermata - <Nome> arriverà il <g> <mese>'
//  B) Airbnb  '<Nome> ha inviato un messaggio' (qui arriva il telefono)
//  C) Booking 'Booking.com - ¡Nueva reserva! (<ref>, <giorno>, <g> de <mese> de <anno>)'
// Output: payload per POST /api/webhooks/bookings, oppure niente.
// ============================================================

// MAPPA STRUTTURE: aggiungi una riga per ogni struttura/cliente.
// 'match' = pezzo del nome annuncio come appare nelle email.
const PROPERTY_MAP = [
  { match: 'Vista Oceano', property_id: 'e617be48-865a-4745-9695-8ae542471e98' },
];
const DEFAULT_PROPERTY_ID = 'e617be48-865a-4745-9695-8ae542471e98';

const j = $json;
const subject = String(j.subject || '');
const fromRaw = JSON.stringify(j.from || '') + ' ' + String(j.sender || '');
const html = String(j.textHtml || j.html || '');
const text = (String(j.textPlain || j.text || '') || html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' '))
  .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');

const MESI = {
  gen:1,gennaio:1,ene:1,enero:1,jan:1,january:1,
  feb:2,febbraio:2,febrero:2,february:2,
  mar:3,marzo:3,march:3,
  apr:4,aprile:4,abr:4,abril:4,april:4,
  mag:5,maggio:5,may:5,mayo:5,
  giu:6,giugno:6,jun:6,junio:6,june:6,
  lug:7,luglio:7,jul:7,julio:7,july:7,
  ago:8,agosto:8,aug:8,august:8,
  set:9,settembre:9,sep:9,septiembre:9,september:9,
  ott:10,ottobre:10,oct:10,octubre:10,october:10,
  nov:11,novembre:11,noviembre:11,november:11,
  dic:12,dicembre:12,diciembre:12,dec:12,december:12,
};

function mese(nome) {
  const k = String(nome || '').toLowerCase().slice(0, 9);
  for (const [key, val] of Object.entries(MESI)) {
    if (k.startsWith(key) || key.startsWith(k.slice(0, 3))) { if (k.slice(0,3) === key.slice(0,3)) return val; }
  }
  return null;
}

function dataISO(giorno, nomeMese, anno) {
  const m = mese(nomeMese);
  if (!m) return null;
  const oggi = new Date();
  let y = anno ? Number(anno) : oggi.getFullYear();
  if (!anno) {
    // inferenza anno: la data deve cadere tra -60 giorni e +18 mesi
    const tenta = new Date(y, m - 1, Number(giorno));
    if (tenta.getTime() < oggi.getTime() - 60 * 86400000) y += 1;
  }
  return `${y}-${String(m).padStart(2, '0')}-${String(giorno).padStart(2, '0')}`;
}

function trovaProperty(testo) {
  for (const r of PROPERTY_MAP) {
    if (testo.toLowerCase().includes(r.match.toLowerCase())) return r.property_id;
  }
  return DEFAULT_PROPERTY_ID;
}

function trovaTelefono(testo) {
  const candidati = testo.match(/(?:\+|00)?[0-9][0-9\s().\-]{6,18}[0-9]/g) || [];
  for (const c of candidati) {
    const cifre = c.replace(/\D/g, '');
    if (cifre.length >= 8 && cifre.length <= 15 && !/^(19|20)\d{2}$/.test(cifre.slice(0, 4))) {
      return c.trim();
    }
  }
  return null;
}

const daAirbnb = /airbnb/i.test(fromRaw) || /airbnb/i.test(subject);
const daBooking = /booking\.com/i.test(fromRaw) || /booking\.com/i.test(subject);
let payload = null;

// ── A) AIRBNB: nuova prenotazione confermata ──
let m = subject.match(/(?:Prenotazione confermata|Reservation confirmed|Nuova prenotazione confermata)[!\s\-–:]*(.+?)\s+(?:arriver|arrives|llega)/iu);
if (daAirbnb && m) {
  const nome = m[1].trim();
  const codice = (text.match(/\b(HM[A-Z0-9]{8})\b/) || text.match(/[Cc]odice di conferma\s*:?\s*([A-Z0-9]{10})/) || [])[1] || null;
  const ci = text.match(/Check-?in[^0-9]{0,30}?(\d{1,2})\s+([a-zà-ù]{3,10})\.?\s*(\d{4})?/i);
  const co = text.match(/Check-?out[^0-9]{0,30}?(\d{1,2})\s+([a-zà-ù]{3,10})\.?\s*(\d{4})?/i);
  const adulti = Number((text.match(/(\d+)\s+adult/i) || [])[1] || 0);
  const bambini = Number((text.match(/(\d+)\s+bambin/i) || text.match(/(\d+)\s+child/i) || [])[1] || 0);
  if (ci && co) {
    let checkin = dataISO(ci[1], ci[2], ci[3]);
    let checkout = dataISO(co[1], co[2], co[3]);
    if (checkin && checkout && checkout <= checkin) {
      const d = new Date(checkout); d.setFullYear(d.getFullYear() + 1);
      checkout = d.toISOString().slice(0, 10);
    }
    if (checkin && checkout) {
      payload = {
        property_id: trovaProperty(text),
        channel: 'airbnb',
        external_id: codice,
        guest_name: nome,
        checkin_date: checkin,
        checkout_date: checkout,
        num_guests: (adulti + bambini) || undefined,
        status: 'confermata',
        notes: 'Importata da email Airbnb. Telefono in arrivo dalla chat (messaggio programmato).',
      };
    }
  }
}

// ── B) AIRBNB: l'ospite ha risposto in chat (cerca il telefono) ──
if (!payload && daAirbnb) {
  const mm = subject.match(/^(?:Re:\s*)?([\p{L}][\p{L}\s'’.\-]{1,40}?)\s+(?:ti\s+)?(?:ha inviato un messaggio|sent you a message|ha risposto)/iu);
  if (mm) {
    const tel = trovaTelefono(text);
    if (tel) {
      payload = {
        property_id: trovaProperty(text),
        channel: 'airbnb',
        guest_name: mm[1].trim(),
        guest_phone: tel,
        match_by_name: true,
      };
    }
  }
}

// ── C) BOOKING.COM: nuova prenotazione (notifica minimale) ──
if (!payload && daBooking && /nueva reserva|nuova prenotazione|new booking|new reservation/i.test(subject)) {
  const ref = (subject.match(/\((\d{6,12})/) || text.match(/(?:confirmation|conferma|confirmación)\s*[—\-:]*\s*(\d{6,12})/i) || [])[1];
  const dm = subject.match(/(\d{1,2})\s+(?:de\s+)?([a-zà-ùñ]{3,12})(?:\s+(?:de\s+)?(\d{4}))?/i);
  if (ref && dm) {
    const checkin = dataISO(dm[1], dm[2], dm[3]);
    if (checkin) {
      const co = new Date(checkin); co.setDate(co.getDate() + 1);
      payload = {
        property_id: trovaProperty(text + ' ' + subject),
        channel: 'booking',
        external_id: ref,
        guest_name: 'Ospite Booking ' + ref,
        checkin_date: checkin,
        checkout_date: co.toISOString().slice(0, 10),
        status: 'da_completare',
        notes: 'Notifica minimale Booking.com: completare nome, telefono e data di partenza dall\'extranet (admin.booking.com).',
      };
    }
  }
}

// ── D) BOOKING.COM: cancellazione ──
if (!payload && daBooking && /cancelad|cancellat|cancelled/i.test(subject)) {
  const ref = (subject.match(/\((\d{6,12})/) || text.match(/(\d{8,12})/) || [])[1];
  if (ref) {
    payload = { property_id: trovaProperty(text + ' ' + subject), channel: 'booking', external_id: ref, status: 'cancellata' };
  }
}

if (!payload) {
  return { json: { skip: true, motivo: 'email non riconosciuta', subject } };
}
return { json: { skip: false, payload } };
